        valid &= np.isfinite(med_dv) & (med_dv >= 1e6)

    if close_raw is not None:
        CR_last = close_raw.reindex(columns=tickers).loc[:asof].iloc[-1].to_numpy(dtype=float)
        valid &= np.isfinite(CR_last) & (CR_last >= 3.0)
